const crypto = require('crypto');
const http = require('http');
const https = require('https');

const executionError = $json?.execution?.error;
const message = executionError?.message;
if (message === 'AUTOMATION_FAILURE_ALREADY_REPORTED') {
  return [{ json: { outcome: 'ALREADY_REPORTED' } }];
}
const prefix = 'AUTOMATION_FAILURE_CONTEXT:';
let encodedContext = null;
if (typeof message === 'string' && message.startsWith(prefix)) {
  encodedContext = message.slice(prefix.length).split(' ')[0];
} else if (executionError?.description === 'AUTOMATION_FAILURE_CONTEXT' && typeof message === 'string') {
  encodedContext = message.split(' ')[0];
} else if (typeof executionError?.stack === 'string') {
  encodedContext = executionError.stack.match(/AUTOMATION_FAILURE_CONTEXT:([A-Za-z0-9_-]+)/)?.[1] || null;
}
if (!encodedContext) {
  return [{ json: { outcome: 'SKIPPED', reason: 'RELIABLE_IDENTIFIERS_UNAVAILABLE' } }];
}

let context;
try {
  context = JSON.parse(Buffer.from(encodedContext, 'base64url').toString('utf8'));
} catch {
  throw new Error('AUTOMATION_FALLBACK_CONTEXT_INVALID');
}
const required = ['eventId', 'runId', 'idempotencyKey', 'workerId', 'n8nExecutionId'];
if (required.some((key) => typeof context[key] !== 'string' || context[key].length === 0)) {
  throw new Error('AUTOMATION_FALLBACK_CONTEXT_INVALID');
}

const baseUrl = $env.AUTOMATION_API_BASE_URL;
const serviceToken = $env.AUTOMATION_SERVICE_TOKEN;
const hmacSecret = $env.AUTOMATION_HMAC_SECRET;
if (!baseUrl || !serviceToken || !hmacSecret) {
  throw new Error('AUTOMATION_CONFIGURATION_INVALID');
}
const path = '/api/internal/automation/failure';
const bodyText = JSON.stringify({
  eventId: context.eventId,
  runId: context.runId,
  idempotencyKey: context.idempotencyKey,
  workerId: context.workerId,
  n8nExecutionId: context.n8nExecutionId,
  failedNode: context.failedNode || 'Unknown node',
  errorCode: 'TEMPORARY_PROVIDER_FAILURE',
  errorMessage: 'The automation consumer failed and its direct failure report did not complete.',
  classification: 'RETRYABLE',
  reportedAt: new Date().toISOString(),
});
const timestamp = String(Math.floor(Date.now() / 1000));
const bodyHash = crypto.createHash('sha256').update(bodyText).digest('hex');
const canonical = `POST\n${path}\n${timestamp}\n${bodyHash}`;
const signature = `sha256=${crypto.createHmac('sha256', hmacSecret).update(canonical).digest('hex')}`;
const target = `${baseUrl}${path}`;
const transport = baseUrl.startsWith('https://') ? https : http;
const status = await new Promise((resolve, reject) => {
  const request = transport.request(target, {
    method: 'POST',
    headers: {
      authorization: `Bearer ${serviceToken}`,
      'content-type': 'application/json',
      'x-automation-timestamp': timestamp,
      'x-automation-signature': signature,
    },
  }, (response) => {
    response.resume();
    response.on('end', () => resolve(response.statusCode || 0));
  });
  request.on('error', reject);
  request.write(bodyText);
  request.end();
});
if (status < 200 || status >= 300) throw new Error('AUTOMATION_FALLBACK_REPORT_REJECTED');
return [{ json: { outcome: 'FAILURE_REPORTED', eventId: context.eventId, runId: context.runId } }];
